import pandas as pd
import math

def correlation_score(sunlight_hours, plant_heights):
    df = pd.DataFrame({'sun': sunlight_hours, 'height': plant_heights})
    corr = df['sun'].corr(df['height'])
    if corr is None or (isinstance(corr, float) and math.isnan(corr)):
        return None
    return round(float(corr), 3)

