import math

def chart_spec(x, y=None):
    if len(x) == 0:
        return {"type": "empty"}

    def is_numeric(seq):
        return all(isinstance(v, (int, float)) and not isinstance(v, bool) for v in seq)

    if y is None:
        if is_numeric(x):
            n = len(x)
            bins = max(1, math.ceil(math.sqrt(n)))
            return {"type": "histogram", "bins": bins, "min": min(x), "max": max(x)}
        categories = sorted(set(x))
        counts = [x.count(c) for c in categories]
        return {"type": "bar", "categories": categories, "counts": counts}

    if is_numeric(x) and is_numeric(y):
        return {"type": "scatter", "n": len(x), "x_range": [min(x), max(x)], "y_range": [min(y), max(y)]}

    categories = sorted(set(x))
    means = []
    for c in categories:
        vals = [y[i] for i in range(len(x)) if x[i] == c]
        means.append(round(sum(vals) / len(vals), 1))
    return {"type": "bar", "categories": categories, "means": means}

def clean_meter_readings(readings):
    valid = []
    for r in readings:
        if isinstance(r, bool):
            continue
        if not isinstance(r, (int, float)):
            continue
        val = float(r)
        if val < 50 or val > 2000:
            continue
        valid.append(round(val, 1))
    return valid

def remove_bounce_taps(taps):
    cleaned = []
    for tap in taps:
        item, price = tap[0], float(tap[1])
        if cleaned and cleaned[-1][0] == item and cleaned[-1][1] == price:
            continue
        cleaned.append([item, price])
    return cleaned

def label_margins(products):
    out = []
    for name, cost, price in products:
        pct = round((price - cost) / price * 100, 1)
        if pct < 20:
            label = "low"
        elif pct < 50:
            label = "medium"
        else:
            label = "high"
        out.append([name, pct, label])
    return out

def clean_ride_log(rides):
    seen = set()
    deduped = []
    for r in rides:
        rider_id, minutes, distance_km = r[0], r[1], r[2]
        key = (rider_id, minutes, distance_km)
        if key in seen:
            continue
        seen.add(key)
        deduped.append((rider_id, minutes, distance_km))

    result = []
    for rider_id, minutes, distance_km in deduped:
        if isinstance(minutes, bool) or not isinstance(minutes, (int, float)):
            continue
        if isinstance(distance_km, bool) or not isinstance(distance_km, (int, float)):
            continue
        if minutes < 1 or minutes > 180:
            continue
        if distance_km <= 0 or distance_km > 50:
            continue
        speed = round(distance_km / (minutes / 60), 1)
        result.append([rider_id, speed])
    return result

